function check(input, actual, expected) {
  const [nums, k] = input;
  if (!Array.isArray(actual)) return false;
  if (expected.length === 0) return actual.length === 0;
  if (actual.length !== nums.length / 3) return false;
  const used = [];
  for (const group of actual) {
    if (!Array.isArray(group) || group.length !== 3) return false;
    if (group.some(v => typeof v !== 'number')) return false;
    if (Math.max(...group) - Math.min(...group) > k) return false;
    used.push(...group);
  }
  const mine = used.slice().sort((a, b) => a - b);
  const given = nums.slice().sort((a, b) => a - b);
  return mine.every((v, i) => v === given[i]);
}

