function validate([nums, k]) {
  if (nums.length < 3 || nums.length > 100000) return 'nums needs 3 to 100000 values.';
  if (nums.length % 3 !== 0) return 'The length of nums must be a multiple of 3.';
  if (nums.some(v => v < 1 || v > 100000)) return 'Each value is between 1 and 100000.';
  if (k < 1 || k > 100000) return 'k is between 1 and 100000.';
  return null;
}

