function divideArray(nums, k) {
  // Backtracking: the first unused position joins every possible pair of unused positions.
  const used = new Array(nums.length).fill(false);
  const groups = [];
  const search = () => {
    const first = used.indexOf(false);
    if (first === -1) return true;
    used[first] = true;
    for (let j = first + 1; j < nums.length; j++) {
      if (used[j]) continue;
      used[j] = true;
      for (let l = j + 1; l < nums.length; l++) {
        if (used[l]) continue;
        const group = [nums[first], nums[j], nums[l]];
        if (Math.max(...group) - Math.min(...group) > k) continue;
        used[l] = true;
        groups.push(group);
        if (search()) return true;
        groups.pop();
        used[l] = false;
      }
      used[j] = false;
    }
    used[first] = false;
    return false;
  };
  return search() ? groups : [];
}

