function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const count = large ? 666 : int(1, 4);
  const top = large ? 100000 : 12;
  const k = large ? int(1, rand() < 0.2 ? 100000 : 2000) : int(1, 5);
  // Clustered inputs always have a valid split; scattered ones usually do not.
  const clustered = rand() < 0.6;
  const nums = [];
  for (let g = 0; g < count; g++) {
    const base = int(1, top - k);
    for (let t = 0; t < 3; t++) nums.push(clustered ? int(base, base + k) : int(1, top));
  }
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums, k];
}
